def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        if history[0][1] == 'D':
            return 'D'
        return 'C'
    if n == 99:
        return 'D'

    opp_d = 0
    my_d = 0
    for me, opp in history:
        if opp == 'D':
            opp_d += 1
        if me == 'D':
            my_d += 1

    if opp_d == 0:
        if my_d == 0:
            if n == 2 or n == 3:
                return 'D'
            return 'C'
        else:
            return 'D'

    last_me, last_opp = history[-1]

    if last_opp == 'D':
        if last_me == 'D':
            if opp_d / n > 0.7:
                return 'D'
            return 'C'
        else:
            if opp_d / n <= 0.4:
                return 'C'
            return 'D'
    else:
        if last_me == 'D':
            return 'C'
        return 'C'
